#!/usr/bin/env python3
"""Build current five-unit public-price coverage; never a quotation or order."""
from pathlib import Path
import csv, hashlib, json
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'docs/procurement'; bom=OUT/'xe-production-bom-2026-10-28.csv'; snap=OUT/'xe-jlc-public-snapshot.json'
snapshot=json.loads(snap.read_text()) if snap.exists() else {'items':[]}; live={r['jlc_part']:r for r in snapshot['items'] if r['model_match']}; table=[]
for row in csv.DictReader(bom.open()):
 qty=int(row['qty_per_device'])
 if row['route']=='PCB_FEATURE':continue
 current=live.get(row['jlc_part'],{})
 table.append({'route':row['route'],'mpn':row['mpn'],'jlc_part':row['jlc_part'],'references':row['references'],'qty_per_device':qty,'installed_qty_five':qty*5,'billed_purchase_qty_five':current.get('five_unit_billed_purchase_qty'),'observed_stock':int(row['observed_stock']) if row['observed_stock'] else None,'observed_date':row['observed_date'] or None,'public_orderable_flag':current.get('orderable_flag'),'public_minimum_purchase_qty':current.get('minimum_purchase_qty'),'public_no_buy_reason':current.get('no_buy_reason'),'observed_unit_price_USD':current.get('applicable_unit_price_USD'),'extended_five_USD':current.get('extended_five_USD'),'price_status':'PUBLIC_PAGE_PRICE_NOT_QUOTE' if current.get('applicable_unit_price_USD') is not None else 'LIVE_QUOTE_REQUIRED','availability_status':row['status'],'source':row['source']})
jlc=[r for r in table if r['route'].startswith('JLC_')];buyer=[r for r in table if r['route']=='BUYER_FINAL_ASSEMBLY'];assert sum(r['qty_per_device'] for r in jlc)==68 and sum(r['installed_qty_five'] for r in jlc)==340;assert {r['references'] for r in buyer}=={'BAT1','CASE','CORD'}
with (OUT/'xe-five-unit-procurement-gap.csv').open('w',newline='') as stream:w=csv.DictWriter(stream,fieldnames=list(table[0]));w.writeheader();w.writerows(table)
all_prices=all(r['observed_unit_price_USD'] is not None for r in jlc);subtotal=round(sum(r['extended_five_USD'] or 0 for r in jlc),6) if all_prices else None
report={'status':'COMPLETE_QUANTITY_COVERAGE_PUBLIC_PART_PRICES_NOT_COMPLETE_QUOTE_DO_NOT_ORDER','date':'2026-10-28','units':5,'jlc_bom_lines':len(jlc),'jlc_positions_per_unit':68,'jlc_installed_five':340,'buyer_final_assembly_lines':len(buyer),'all_line_prices_complete':all_prices,'known_price_subtotal_USD':subtotal,'pcb_fabrication_USD':None,'pofv_USD':None,'assembly_USD':None,'parts_USD':None,'inspection_USD':None,'factory_programming_USD':None,'case_and_cord_USD':None,'battery_USD':None,'freight_tax_USD':None,'complete_five_unit_landed_USD':None,'price_rule':'Public part prices are not a PCBA quote. Null means unknown and must never be treated as zero.','table':'docs/procurement/xe-five-unit-procurement-gap.csv','table_sha256':hashlib.sha256((OUT/'xe-five-unit-procurement-gap.csv').read_bytes()).hexdigest(),'source_bom_sha256':hashlib.sha256(bom.read_bytes()).hexdigest(),'public_snapshot_sha256':hashlib.sha256(snap.read_bytes()).hexdigest() if snap.exists() else None,'orders_payments_uploads_vendor_contacts_performed':False}
(OUT/'xe-five-unit-procurement-gap.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':report['status'],'priced':sum(r['observed_unit_price_USD'] is not None for r in jlc),'jlc_lines':len(jlc),'part_subtotal':subtotal,'complete_total':None}))
